   516	        }
   517	
   518	        if (njs_slow_path(ret != NJS_OK)) {
   519	            return NJS_ERROR;
   520	        }
   521	    }
   522	
   523	object:
   524	
   525	    ret = njs_object_own_enumerate_object(vm, object, parent, items, kind,
   526	                                          type, all);
   527	    if (njs_slow_path(ret != NJS_OK)) {
